setup_files.user_loader.ts:
interface User {
  name: string;
}

const USERS: Record<number, User> = {
  1: { name: "ada" },
  2: { name: "grace" },
};

function fetchUser(id: number): Promise<User> {
  return new Promise((resolve, reject) => {
    const user = USERS[id];
    if (user) {
      resolve(user);
    } else {
      reject(new Error(`no user ${id}`));
    }
  });
}

// Load a user's display name; unknown ids resolve to "guest".
export function displayName(id: number): Promise<string> {
  return fetchUser(id)
    .then((user) => user.name)
    .then((name) => name.toUpperCase())
    .catch(() => "guest");
}

