const assert = require("assert");
const { displayName } = require("./build/user_loader.js");

async function main() {
  assert.strictEqual(await displayName(1), "ADA");
  assert.strictEqual(await displayName(2), "GRACE");
  assert.strictEqual(await displayName(99), "guest", "unknown ids must fall back to guest");
  console.log("behavior OK");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

